template<>struct Wire<UD_MESSAGE> {static Json Encode(const UD_MESSAGE& v){Json j=Json::object();j["magic"]=EncodeWire(v.magic);j["version"]=EncodeWire(v.version);j["command"]=EncodeWire(v.command);j["reserved"]=EncodeWire(v.reserved);j["generation"]=EncodeWire(v.generation);j["id"]=EncodeWire(v.id);j["offset"]=EncodeWire(v.offset);j["length"]=EncodeWire(v.length);j["result"]=EncodeWire(v.result);j["capacity"]=EncodeWire(v.capacity);j["readonly"]=EncodeWire(v.readonly);j["operation"]=EncodeWire(v.operation);j["data"]=EncodeWire(v.data);return j;}static void Decode(const Json& j,UD_MESSAGE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="magic")DecodeWire(it.value(),v.magic);else if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="command")DecodeWire(it.value(),v.command);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else if(it.key()=="generation")DecodeWire(it.value(),v.generation);else if(it.key()=="id")DecodeWire(it.value(),v.id);else if(it.key()=="offset")DecodeWire(it.value(),v.offset);else if(it.key()=="length")DecodeWire(it.value(),v.length);else if(it.key()=="result")DecodeWire(it.value(),v.result);else if(it.key()=="capacity")DecodeWire(it.value(),v.capacity);else if(it.key()=="readonly")DecodeWire(it.value(),v.readonly);else if(it.key()=="operation")DecodeWire(it.value(),v.operation);else if(it.key()=="data")DecodeWire(it.value(),v.data);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
